import Foundation

/// Interface phrases. English is the source. A missing or junk translation
/// always shows the English line — the window still draws.
@MainActor
enum InterfaceStore {
    static let codeKey = "interfaceLang"
    static let pendingKey = "interfaceLangPending"
    static let unhealthyKey = "interfaceLangUnhealthy"
    static let extraKey = "interfaceExtraLangs"

    private static let bundled = Set(["en", "es", "nl"])

    static var code: String {
        get { UserDefaults.standard.string(forKey: codeKey) ?? "en" }
        set { UserDefaults.standard.set(newValue, forKey: codeKey) }
    }

    static var extraCodes: [String] {
        UserDefaults.standard.stringArray(forKey: extraKey) ?? []
    }

    static func isBundled(_ lang: String) -> Bool {
        bundled.contains(lang)
    }

    /// Language names stay in English so the picker is readable after a swap.
    static let keepEnglish: Set<String> = {
        var names: Set<String> = ["US English", "Spanish", "Dutch", "English"]
        names.formUnion(TranslateLang.spoken.map(\.label))
        names.insert(TranslateLang.auto.label)
        return names
    }()

    static func look(_ english: String) -> String {
        let lang = code
        if lang == "en" || english.isEmpty { return english }
        if keepEnglish.contains(english) { return english }
        if let hit = overlay[english], !hit.isEmpty { return hit }
        return english
    }

    static var overlay: [String: String] = [:]

    @discardableResult
    static func recoverIfNeeded() -> Bool {
        let stored = UserDefaults.standard.string(forKey: codeKey) ?? "en"
        let pending = UserDefaults.standard.bool(forKey: pendingKey)
        let unhealthy = UserDefaults.standard.bool(forKey: unhealthyKey)
        if stored != "en", pending || (unhealthy && !isBundled(stored)) {
            apply("en", markPending: false)
            UserDefaults.standard.set(false, forKey: pendingKey)
            UserDefaults.standard.set(false, forKey: unhealthyKey)
            return true
        }
        apply(stored, markPending: false)
        return false
    }

    static func apply(_ lang: String, markPending: Bool) {
        let next = normalize(lang)
        code = next
        if markPending, next != "en" {
            UserDefaults.standard.set(true, forKey: pendingKey)
        }
        overlay = table(for: next)
    }

    static func markHealthy() {
        UserDefaults.standard.set(false, forKey: pendingKey)
    }

    static func normalize(_ raw: String) -> String {
        let t = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        if t.isEmpty { return "en" }
        return t
    }

    static func table(for lang: String) -> [String: String] {
        switch lang {
        case "es": return spanish
        case "nl": return dutch
        case "en": return [:]
        default:
            return loadExtra(lang) ?? [:]
        }
    }

    static func catalogKeys() -> [String] {
        Array(Set(spanish.keys).union(dutch.keys).subtracting(keepEnglish)).sorted()
    }

    static func saveExtra(code lang: String, table: [String: String]) {
        let clean = lang.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !clean.isEmpty, clean != "en" else { return }
        let url = extraURL(clean)
        try? FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        if let data = try? JSONSerialization.data(withJSONObject: table, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: url, options: .atomic)
        }
        var extras = extraCodes
        if !extras.contains(clean) {
            extras.append(clean)
            extras.sort()
            UserDefaults.standard.set(extras, forKey: extraKey)
        }
    }

    private static func loadExtra(_ lang: String) -> [String: String]? {
        let url = extraURL(lang)
        guard let data = try? Data(contentsOf: url),
              let obj = try? JSONSerialization.jsonObject(with: data) as? [String: String],
              !obj.isEmpty
        else { return nil }
        return obj
    }

    private static func extraURL(_ lang: String) -> URL {
        let appSupport = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first
            ?? FileManager.default.homeDirectoryForCurrentUser
        return appSupport
            .appendingPathComponent("yourMark", isDirectory: true)
            .appendingPathComponent("interface", isDirectory: true)
            .appendingPathComponent("\(lang).json")
    }

